-- ═══════════════════════════════════════════════════════════════

BEGIN;

INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Mercury', 'Cessily Kincaid', 'novatos', 'medio', '{"iniciativa":18,"stats":{"destreza":7,"força":4,"corpo":6,"inteligência":6,"vontade":6,"mente":6,"influência":5,"aura":7,"espírito":6},"temas":[{"nome":"Corpo de Metal Líquido","poder":[{"texto":"Metamorfose de Metal Líquido"},{"texto":"Membros Elásticos e Extensíveis"},{"texto":"Regeneração Física Instantânea"},{"texto":"Resistência a Impacto e Perfuração"},{"texto":"Fusão e Reforma após Fragmentação"}],"fraqueza":[]},{"nome":"Escultura em Combate","poder":[{"texto":"Formas de Lâmina e Escudo Improvisadas"},{"texto":"Alongamento para Alcance Estendido"},{"texto":"Achatamento e Passagem por Frestas"},{"texto":"Reflexos Metálicos Aprimorados"},{"texto":"Superfície Cortante sob Comando"}],"fraqueza":[]},{"nome":"Aluna dos Hellions","poder":[{"texto":"Sociável apesar da Aparência"},{"texto":"Lealdade Feroz aos Hellions"},{"texto":"Senso de Humor Autodepreciativo"},{"texto":"Empatia por Outros Considerados Estranhos"},{"texto":"Coragem para se Expor em Público"}],"fraqueza":[{"texto":"Insegurança Profunda com o Próprio Corpo"}]},{"nome":"Vulnerabilidades do Metal","poder":[],"fraqueza":[{"texto":"Vulnerável a Manipulação Magnética"},{"texto":"Fragiliza-se e Perde Fluidez no Frio Extremo"},{"texto":"Medo de Ser Vista como Monstro"}]}],"tags":[{"texto":"Metamorfose de Metal Líquido"},{"texto":"Membros Elásticos e Extensíveis"},{"texto":"Regeneração Física Instantânea"},{"texto":"Resistência a Impacto e Perfuração"},{"texto":"Fusão e Reforma após Fragmentação"},{"texto":"Formas de Lâmina e Escudo Improvisadas"},{"texto":"Alongamento para Alcance Estendido"},{"texto":"Achatamento e Passagem por Frestas"},{"texto":"Reflexos Metálicos Aprimorados"},{"texto":"Superfície Cortante sob Comando"},{"texto":"Sociável apesar da Aparência"},{"texto":"Lealdade Feroz aos Hellions"},{"texto":"Senso de Humor Autodepreciativo"},{"texto":"Empatia por Outros Considerados Estranhos"},{"texto":"Coragem para se Expor em Público"}],"descricao":"Cessily Kincaid descobriu sua mutação da pior forma possível: acordou uma manhã com o próprio corpo derretendo em metal líquido, um trauma que moldou anos de insegurança. Hoje controla a forma fluida com uma graça que impressiona até os professores, alongando membros e assumindo formas de combate improvisadas. Apesar da aparência que muitos chamam de assustadora, é uma das alunas mais gentis e leais dos Hellions. Ainda assim, carrega o medo silencioso de nunca mais parecer \"normal\" aos olhos dos outros.","esquadrao":"Hellions"}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Mercury' AND is_global = TRUE);

INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Tag', 'Brian Cruz', 'novatos', 'medio', '{"iniciativa":18,"stats":{"destreza":6,"força":4,"corpo":5,"inteligência":6,"vontade":6,"mente":7,"influência":6,"aura":6,"espírito":6},"temas":[{"nome":"Toque Mimético","poder":[{"texto":"Cópia Temporária de Poderes por Toque"},{"texto":"Absorção de Habilidades e Talentos Alheios"},{"texto":"Retém Cópia por Minutos Após o Contato"},{"texto":"Combina Múltiplas Cópias em Sequência"},{"texto":"Aprendizado Instantâneo de Técnicas de Combate"}],"fraqueza":[]},{"nome":"Camaleão de Talentos","poder":[{"texto":"Adaptação Tática Rápida em Combate"},{"texto":"Leitura de Padrões de Luta do Alvo"},{"texto":"Versatilidade Contra Ameaças Variadas"},{"texto":"Memória Muscular Emprestada"},{"texto":"Improviso sob Pressão"}],"fraqueza":[]},{"nome":"Aluno Observador","poder":[{"texto":"Perceptivo e Estratégico"},{"texto":"Popular entre os Hellions"},{"texto":"Curiosidade Insaciável sobre Poderes Alheios"},{"texto":"Charme Descontraído"},{"texto":"Vontade de Provar seu Valor"}],"fraqueza":[{"texto":"Depende do Contato Físico para Agir"}]},{"nome":"Identidade Emprestada","poder":[],"fraqueza":[{"texto":"Sem Poder Próprio Fixo"},{"texto":"Cópia Instável sob Estresse Emocional"},{"texto":"Medo de Nunca Ter uma Identidade Só Sua"}]}],"tags":[{"texto":"Cópia Temporária de Poderes por Toque"},{"texto":"Absorção de Habilidades e Talentos Alheios"},{"texto":"Retém Cópia por Minutos Após o Contato"},{"texto":"Combina Múltiplas Cópias em Sequência"},{"texto":"Aprendizado Instantâneo de Técnicas de Combate"},{"texto":"Adaptação Tática Rápida em Combate"},{"texto":"Leitura de Padrões de Luta do Alvo"},{"texto":"Versatilidade Contra Ameaças Variadas"},{"texto":"Memória Muscular Emprestada"},{"texto":"Improviso sob Pressão"},{"texto":"Perceptivo e Estratégico"},{"texto":"Popular entre os Hellions"},{"texto":"Curiosidade Insaciável sobre Poderes Alheios"},{"texto":"Charme Descontraído"},{"texto":"Vontade de Provar seu Valor"}],"descricao":"Brian Cruz tem o dom raro de copiar qualquer habilidade que toca, de um golpe de artes marciais a um talento para xadrez, guardando a cópia por poucos minutos preciosos. Popular e curioso, adora testar seus limites contra colegas mais poderosos só para ver o que consegue emprestar. Nos Hellions, é o coringa da equipe — nunca o mais forte sozinho, mas sempre o mais imprevisível em grupo. No fundo, teme que, sem o toque de outra pessoa, não tenha nada que seja realmente seu.","esquadrao":"Hellions"}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Tag' AND is_global = TRUE);

INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Wither', 'Kevin Ford', 'novatos', 'medio', '{"iniciativa":15,"stats":{"destreza":6,"força":5,"corpo":6,"inteligência":5,"vontade":7,"mente":6,"influência":4,"aura":5,"espírito":5},"temas":[{"nome":"Mão da Decadência","poder":[{"texto":"Toque que Apodrece Carne e Matéria Vegetal"},{"texto":"Desidratação Instantânea ao Contato"},{"texto":"Controle sobre a Velocidade da Decomposição"},{"texto":"Sente a Vitalidade de Seres Próximos"},{"texto":"Pode Direcionar o Apodrecimento a Distância Curta"}],"fraqueza":[]},{"nome":"Esqueleto Vivo","poder":[{"texto":"Mão Reduzida a Osso Imune ao Próprio Poder"},{"texto":"Golpes Físicos com a Mão Óssea"},{"texto":"Resistência a Dor na Extremidade Afetada"},{"texto":"Presença Intimidadora em Combate"},{"texto":"Precisão Cirúrgica no Toque"}],"fraqueza":[]},{"nome":"Ex-Academia Hellfire","poder":[{"texto":"Treinamento Rigoroso da Academia Hellfire"},{"texto":"Disciplina de Combate Silenciosa"},{"texto":"Escolheu o Caminho do Bem por Conta Própria"},{"texto":"Lealdade Cautelosa aos Novos Colegas"},{"texto":"Instinto de Sobrevivência Aguçado"}],"fraqueza":[{"texto":"Isolamento Social Autoimposto"}]},{"nome":"Peso do Próprio Poder","poder":[],"fraqueza":[{"texto":"Não Pode Tocar Ninguém sem Ferir"},{"texto":"Brooding e Desconfiado por Natureza"},{"texto":"Passado Sombrio na Academia Hellfire"}]}],"tags":[{"texto":"Toque que Apodrece Carne e Matéria Vegetal"},{"texto":"Desidratação Instantânea ao Contato"},{"texto":"Controle sobre a Velocidade da Decomposição"},{"texto":"Sente a Vitalidade de Seres Próximos"},{"texto":"Pode Direcionar o Apodrecimento a Distância Curta"},{"texto":"Mão Reduzida a Osso Imune ao Próprio Poder"},{"texto":"Golpes Físicos com a Mão Óssea"},{"texto":"Resistência a Dor na Extremidade Afetada"},{"texto":"Presença Intimidadora em Combate"},{"texto":"Precisão Cirúrgica no Toque"},{"texto":"Treinamento Rigoroso da Academia Hellfire"},{"texto":"Disciplina de Combate Silenciosa"},{"texto":"Escolheu o Caminho do Bem por Conta Própria"},{"texto":"Lealdade Cautelosa aos Novos Colegas"},{"texto":"Instinto de Sobrevivência Aguçado"}],"descricao":"Kevin Ford perdeu o controle da própria mão antes de perder a inocência: um toque acidental bastou para reduzi-la a osso, e desde então carrega a decomposição como uma sentença. Treinado ainda jovem na sombria Academia Hellfire, escolheu deixar esse caminho para trás e tentar, sozinho, se tornar algo melhor. É reservado, observa mais do que fala, e prefere manter distância física de todos — não por frieza, mas por medo genuíno de machucar quem se aproxima. Sob a superfície sombria, esconde uma vontade desesperada de pertencer a algo bom.","esquadrao":"Hellions"}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Wither' AND is_global = TRUE);

INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Icarus', 'Jay Guthrie', 'novatos', 'baixo', '{"iniciativa":16,"stats":{"destreza":6,"força":4,"corpo":5,"inteligência":5,"vontade":5,"mente":5,"influência":5,"aura":6,"espírito":6},"temas":[{"nome":"Asas dos Guthrie","poder":[{"texto":"Grandes Asas Emplumadas"},{"texto":"Voo Ágil e Sustentado"},{"texto":"Visão Aguçada em Altitude"},{"texto":"Manobras Aéreas Evasivas"}],"fraqueza":[]},{"nome":"Irmão Protetor","poder":[{"texto":"Membro da Família Guthrie (irmão de Cannonball e Husk)"},{"texto":"Instinto Protetor com Colegas Mais Novos"},{"texto":"Gentileza Incomum para um Herói em Formação"},{"texto":"Determinação Silenciosa"}],"fraqueza":[{"texto":"Sombra dos Irmãos Mais Famosos"}]},{"nome":"Ainda Aprendendo a Voar","poder":[],"fraqueza":[{"texto":"Controle de Voo Ainda Instável em Ventos Fortes"},{"texto":"Timidez que o Faz Hesitar em Combate"}]}],"tags":[{"texto":"Grandes Asas Emplumadas"},{"texto":"Voo Ágil e Sustentado"},{"texto":"Visão Aguçada em Altitude"},{"texto":"Manobras Aéreas Evasivas"},{"texto":"Membro da Família Guthrie (irmão de Cannonball e Husk)"},{"texto":"Instinto Protetor com Colegas Mais Novos"},{"texto":"Gentileza Incomum para um Herói em Formação"},{"texto":"Determinação Silenciosa"}],"descricao":"Jay Guthrie cresceu à sombra de irmãos mais famosos — Cannonball e Husk já eram lendas no Instituto antes mesmo de suas asas surgirem. Gentil e desajeitado no ar, ainda aprende a confiar totalmente nas próprias penas, especialmente quando o vento vira contra ele. É o tipo de aluno que se lança na frente de um colega em perigo antes de pensar duas vezes. Sonha em um dia ser lembrado por seu próprio nome, não apenas como \"mais um Guthrie\".","esquadrao":"New Mutants"}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Icarus' AND is_global = TRUE);

INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Wind Dancer', 'Sofia Mantega', 'novatos', 'medio', '{"iniciativa":19,"stats":{"destreza":7,"força":4,"corpo":5,"inteligência":6,"vontade":6,"mente":6,"influência":6,"aura":7,"espírito":6},"temas":[{"nome":"Senhora dos Ventos","poder":[{"texto":"Controle de Correntes de Ar"},{"texto":"Rajadas de Vento Ofensivas"},{"texto":"Voo Limitado por Sustentação Aérea"},{"texto":"Criação de Redemoinhos Defensivos"},{"texto":"Amortecimento de Quedas com Ar"}],"fraqueza":[]},{"nome":"Leitura das Correntes","poder":[{"texto":"Sente Mudanças Climáticas Iminentes"},{"texto":"Precisão em Direcionar Ventos"},{"texto":"Dispersão de Gases e Fumaça"},{"texto":"Empurrões Teleguiados a Distância"},{"texto":"Guia Detritos e Objetos Levados pelo Vento"}],"fraqueza":[]},{"nome":"Alma Brasileira","poder":[{"texto":"Calorosa e Sociável com Todos"},{"texto":"Otimismo Contagiante"},{"texto":"Habilidade para Unir o Grupo"},{"texto":"Saudade Constante de Casa"},{"texto":"Fluente em Português e Inglês"}],"fraqueza":[{"texto":"Impulsiva ao Confiar Rápido Demais"}]},{"nome":"Limites do Vento","poder":[],"fraqueza":[{"texto":"Poder Enfraquece em Espaços Fechados"},{"texto":"Cansaço Físico após Rajadas Prolongadas"},{"texto":"Frustração por Não Voar Livremente"}]}],"tags":[{"texto":"Controle de Correntes de Ar"},{"texto":"Rajadas de Vento Ofensivas"},{"texto":"Voo Limitado por Sustentação Aérea"},{"texto":"Criação de Redemoinhos Defensivos"},{"texto":"Amortecimento de Quedas com Ar"},{"texto":"Sente Mudanças Climáticas Iminentes"},{"texto":"Precisão em Direcionar Ventos"},{"texto":"Dispersão de Gases e Fumaça"},{"texto":"Empurrões Teleguiados a Distância"},{"texto":"Guia Detritos e Objetos Levados pelo Vento"},{"texto":"Calorosa e Sociável com Todos"},{"texto":"Otimismo Contagiante"},{"texto":"Habilidade para Unir o Grupo"},{"texto":"Saudade Constante de Casa"},{"texto":"Fluente em Português e Inglês"}],"descricao":"Sofia Mantega trouxe do Brasil um sorriso fácil e um talento raro para comandar o vento como se ele fosse uma extensão de seu próprio corpo. É o tipo de aluna que conhece o nome de todos no corredor e organiza o grupo antes mesmo de qualquer professor perceber que algo deu errado. Sente saudades constantes de casa, mas encontrou nos Novos Mutantes uma segunda família que preenche parte desse vazio. Confia rápido demais nas pessoas — uma qualidade linda que também já a colocou em perigo mais de uma vez.","esquadrao":"New Mutants"}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Wind Dancer' AND is_global = TRUE);

INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'DJ', 'DJ', 'novatos', 'medio', '{"iniciativa":20,"stats":{"destreza":7,"força":4,"corpo":5,"inteligência":6,"vontade":6,"mente":6,"influência":7,"aura":7,"espírito":6},"temas":[{"nome":"Mestre do Som","poder":[{"texto":"Manipulação Sônica através de Música"},{"texto":"Ondas de Choque Rítmicas"},{"texto":"Amplificação de Frequências Ofensivas"},{"texto":"Criação de Barreiras Sonoras"},{"texto":"Controle de Volume e Tom à Vontade"},{"texto":"Ressonância que Racha Vidro e Metal Fino"}],"fraqueza":[]},{"nome":"Toca-Discos Vivo","poder":[{"texto":"Scratches que Distorcem a Realidade Sonora Local"},{"texto":"Batidas que Desorientam Inimigos"},{"texto":"Mixagem de Efeitos em Tempo Real"},{"texto":"Amplificadores Portáteis Improvisados"},{"texto":"Loop de Batidas para Sustentar Efeitos"}],"fraqueza":[]},{"nome":"Performer Nato","poder":[{"texto":"Carisma de Palco Inegável"},{"texto":"Energia que Contagia a Plateia"},{"texto":"Competitividade Saudável nas Batalhas de Som"},{"texto":"Talento Musical Reconhecido no Instituto"}],"fraqueza":[{"texto":"Vaidade que Busca Sempre os Holofotes"}]},{"nome":"Sem Show, Sem Poder","poder":[],"fraqueza":[{"texto":"Precisa de Equipamento ou Fonte Sonora para o Máximo Efeito"},{"texto":"Ouvidos Sensíveis a Sons Muito Altos"},{"texto":"Ansiedade Quando Fora do Centro das Atenções"}]}],"tags":[{"texto":"Manipulação Sônica através de Música"},{"texto":"Ondas de Choque Rítmicas"},{"texto":"Amplificação de Frequências Ofensivas"},{"texto":"Criação de Barreiras Sonoras"},{"texto":"Controle de Volume e Tom à Vontade"},{"texto":"Ressonância que Racha Vidro e Metal Fino"},{"texto":"Scratches que Distorcem a Realidade Sonora Local"},{"texto":"Batidas que Desorientam Inimigos"},{"texto":"Mixagem de Efeitos em Tempo Real"},{"texto":"Amplificadores Portáteis Improvisados"},{"texto":"Loop de Batidas para Sustentar Efeitos"},{"texto":"Carisma de Palco Inegável"},{"texto":"Energia que Contagia a Plateia"},{"texto":"Competitividade Saudável nas Batalhas de Som"},{"texto":"Talento Musical Reconhecido no Instituto"}],"descricao":"Ninguém sabe seu nome verdadeiro além dos professores — para o resto do Instituto, ele é simplesmente DJ, o garoto que transforma batidas em armas e festas em treinos de combate. Nasceu com a capacidade de manipular som através de música, e desde cedo descobriu que uma boa batida podia derrubar um adversário tão bem quanto qualquer rajada. Vive para os holofotes e para as batalhas de som que organiza nos Paragons, competindo tanto quanto se diverte. Por trás da confiança de palco, teme profundamente o silêncio — e o que aconteceria se um dia ninguém mais quisesse ouvir.","esquadrao":"Paragons"}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'DJ' AND is_global = TRUE);

INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Match', 'Ben Hammil', 'novatos', 'medio', '{"iniciativa":18,"stats":{"destreza":7,"força":5,"corpo":6,"inteligência":5,"vontade":6,"mente":5,"influência":6,"aura":7,"espírito":6},"temas":[{"nome":"Chama Viva","poder":[{"texto":"Combustão Corporal Sem Autodano"},{"texto":"Voo por Propulsão de Fogo"},{"texto":"Rajadas de Fogo Concentradas"},{"texto":"Resistência Total a Calor e Fogo"},{"texto":"Controle de Intensidade da Chama"},{"texto":"Escudo de Chamas Defensivo"}],"fraqueza":[]},{"nome":"Piloto de Fogo","poder":[{"texto":"Manobras Aéreas Agressivas em Combate"},{"texto":"Aterrissagens Explosivas Controladas"},{"texto":"Trilhas de Fumaça para Cobertura"},{"texto":"Acender Objetos à Distância Curta"},{"texto":"Explosões de Curto Alcance ao Pousar"}],"fraqueza":[]},{"nome":"Competidor Nato","poder":[{"texto":"Confiança Inabalável em Combate"},{"texto":"Espírito Competitivo entre os Paragons"},{"texto":"Liderança pelo Exemplo"},{"texto":"Energia Positiva que Motiva a Equipe"}],"fraqueza":[{"texto":"Impulsividade que Ignora o Plano de Equipe"}]},{"nome":"Fogo Sem Freio","poder":[],"fraqueza":[{"texto":"Risco de Incendiar Arredores sem Querer"},{"texto":"Arrogância Diante de Ameaças Maiores"},{"texto":"Dificuldade em Aceitar Derrota"}]}],"tags":[{"texto":"Combustão Corporal Sem Autodano"},{"texto":"Voo por Propulsão de Fogo"},{"texto":"Rajadas de Fogo Concentradas"},{"texto":"Resistência Total a Calor e Fogo"},{"texto":"Controle de Intensidade da Chama"},{"texto":"Escudo de Chamas Defensivo"},{"texto":"Manobras Aéreas Agressivas em Combate"},{"texto":"Aterrissagens Explosivas Controladas"},{"texto":"Trilhas de Fumaça para Cobertura"},{"texto":"Acender Objetos à Distância Curta"},{"texto":"Explosões de Curto Alcance ao Pousar"},{"texto":"Confiança Inabalável em Combate"},{"texto":"Espírito Competitivo entre os Paragons"},{"texto":"Liderança pelo Exemplo"},{"texto":"Energia Positiva que Motiva a Equipe"}],"descricao":"Ben Hammil descobriu que podia se incendiar sem se ferir numa aula de química que quase deu muito errado, e nunca mais parou de voar em chamas desde então. Competitivo até os ossos, encara treinos dos Paragons como se fossem campeonatos, sempre com um sorriso confiante estampado no rosto. É o primeiro a se oferecer para qualquer desafio perigoso, o que rende tanto admiração quanto broncas constantes dos professores. Sua maior batalha não é contra inimigos, mas contra a própria arrogância diante de ameaças que subestima.","esquadrao":"Paragons"}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Match' AND is_global = TRUE);

INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Pixie', 'Megan Gwynn', 'novatos', 'medio', '{"iniciativa":19,"stats":{"destreza":7,"força":3,"corpo":4,"inteligência":6,"vontade":6,"mente":6,"influência":6,"aura":7,"espírito":7},"temas":[{"nome":"Pó de Fada","poder":[{"texto":"Pó Alucinógeno que Induz Ilusões de Medo"},{"texto":"Nuvem de Pó que Confunde os Sentidos"},{"texto":"Asas de Inseto para Voo Ágil"},{"texto":"Controle Fino sobre a Concentração do Pó"},{"texto":"Ilusões Ajustadas ao Maior Medo do Alvo"},{"texto":"Rastro de Brilho que Revela Trajeto"}],"fraqueza":[]},{"nome":"Voo de Libélula","poder":[{"texto":"Manobras Aéreas Rápidas e Erráticas"},{"texto":"Esquiva em Alta Velocidade"},{"texto":"Pousos Precisos em Espaços Apertados"},{"texto":"Perseguição Aérea Persistente"},{"texto":"Sentidos Aguçados para Detectar Movimento"}],"fraqueza":[]},{"nome":"Pequena e Energética","poder":[{"texto":"Energia Inesgotável e Entusiasmo"},{"texto":"Curiosidade que a Leva a Explorar Riscos"},{"texto":"Lealdade Inabalável aos Amigos"},{"texto":"Bom Humor Mesmo sob Pressão"}],"fraqueza":[{"texto":"Recklessness que Ignora o Perigo"}]},{"nome":"Pó Sem Controle","poder":[],"fraqueza":[{"texto":"Pó Pode Afetar Aliados por Engano"},{"texto":"Pequena Estatura Limita Força Física"},{"texto":"Medo de Não Ser Levada a Sério"}]}],"tags":[{"texto":"Pó Alucinógeno que Induz Ilusões de Medo"},{"texto":"Nuvem de Pó que Confunde os Sentidos"},{"texto":"Asas de Inseto para Voo Ágil"},{"texto":"Controle Fino sobre a Concentração do Pó"},{"texto":"Ilusões Ajustadas ao Maior Medo do Alvo"},{"texto":"Rastro de Brilho que Revela Trajeto"},{"texto":"Manobras Aéreas Rápidas e Erráticas"},{"texto":"Esquiva em Alta Velocidade"},{"texto":"Pousos Precisos em Espaços Apertados"},{"texto":"Perseguição Aérea Persistente"},{"texto":"Sentidos Aguçados para Detectar Movimento"},{"texto":"Energia Inesgotável e Entusiasmo"},{"texto":"Curiosidade que a Leva a Explorar Riscos"},{"texto":"Lealdade Inabalável aos Amigos"},{"texto":"Bom Humor Mesmo sob Pressão"}],"descricao":"Megan Gwynn é pequena, rápida e movida a uma energia que parece nunca se esgotar, voando pelos corredores do Instituto em asas que mal cabem em salas de aula comuns. Seu pó de fada pode tanto encantar quanto aterrorizar — capaz de conjurar as piores ilusões de medo de quem o respira. Adora explorar cada canto proibido do campus, o que a coloca em apuros com uma frequência preocupante. Debaixo da irreverência, só quer ser levada a sério por alguém além de si mesma.","esquadrao":"Paragons"}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Pixie' AND is_global = TRUE);

INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
