entes Sobrenaturais"},{"texto":"Explora Locais Distantes sem Se Mover"},{"texto":"Serena e Observadora"},{"texto":"Sabedoria Além da Idade"},{"texto":"Conforto que Oferece aos Colegas Perturbados"},{"texto":"Empatia Silenciosa que Acalma"}],"descricao":"Hope Abbott passa mais tempo fora do próprio corpo do que dentro dele, projetando o espírito para explorar o Instituto e além enquanto o corpo físico dorme tranquilo em algum canto esquecido. Serena a ponto de parecer distante, carrega uma sabedoria que surpreende quem espera encontrar apenas mais uma adolescente. Os colegas dos Paragons já se acostumaram a encontrá-la catatônica em salas vazias, sabendo que sua mente está em algum lugar bem mais interessante. Teme, ainda que raramente admita, o dia em que não conseguir voltar a tempo para o próprio corpo.","esquadrao":"Paragons"}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Trance' AND is_global = TRUE);

INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Wolf Cub', 'Nicholas Gleason', 'novatos', 'medio', '{"iniciativa":15,"stats":{"destreza":7,"força":6,"corpo":6,"inteligência":4,"vontade":5,"mente":4,"influência":4,"aura":6,"espírito":5},"temas":[{"nome":"Transformação Lupina","poder":[{"texto":"Transformação em Forma Lupina Bípede"},{"texto":"Garras e Presas Afiadas"},{"texto":"Força e Velocidade Ampliadas na Forma Animal"},{"texto":"Sentidos Aguçados de Olfato e Audição"},{"texto":"Pelagem que Resiste a Cortes Superficiais"},{"texto":"Salto Poderoso das Patas Traseiras"},{"texto":"Uivo que Coordena Aliados a Distância"}],"fraqueza":[]},{"nome":"Instinto de Matilha","poder":[{"texto":"Rastreamento por Cheiro a Longa Distância"},{"texto":"Visão Noturna Aprimorada"},{"texto":"Reflexos de Predador em Combate"},{"texto":"Mordida com Força de Esmagamento"}],"fraqueza":[]},{"nome":"Garoto Selvagem","poder":[{"texto":"Lealdade Instintiva a Quem Considera Matilha"},{"texto":"Energia Física Incansável"},{"texto":"Determinação Bruta para Proteger os Amigos"},{"texto":"Protetor Fiel dos Mais Fracos"}],"fraqueza":[{"texto":"Dificuldade em Controlar a Fera ao se Enfurecer"}]},{"nome":"A Fera Dentro","poder":[],"fraqueza":[{"texto":"Perde Racionalidade em Fúria Extrema"},{"texto":"Comunicação Verbal Prejudicada na Forma Plena"},{"texto":"Medo de Machucar Quem Ama sem Querer"}]}],"tags":[{"texto":"Transformação em Forma Lupina Bípede"},{"texto":"Garras e Presas Afiadas"},{"texto":"Força e Velocidade Ampliadas na Forma Animal"},{"texto":"Sentidos Aguçados de Olfato e Audição"},{"texto":"Pelagem que Resiste a Cortes Superficiais"},{"texto":"Salto Poderoso das Patas Traseiras"},{"texto":"Uivo que Coordena Aliados a Distância"},{"texto":"Rastreamento por Cheiro a Longa Distância"},{"texto":"Visão Noturna Aprimorada"},{"texto":"Reflexos de Predador em Combate"},{"texto":"Mordida com Força de Esmagamento"},{"texto":"Lealdade Instintiva a Quem Considera Matilha"},{"texto":"Energia Física Incansável"},{"texto":"Determinação Bruta para Proteger os Amigos"},{"texto":"Protetor Fiel dos Mais Fracos"}],"descricao":"Nicholas Gleason carrega um lobo dentro de si que se recusa a ficar quieto, transformando-se em uma fera bípede de garras e instintos sempre que a adrenalina toma conta. É leal ao extremo com quem considera parte de sua matilha, protegendo os Paragons com uma ferocidade que surpreende até os professores mais experientes. Fora de combate, é brincalhão e cheio de energia, quase incapaz de ficar parado por muito tempo. Seu maior medo não é a própria força, mas perder o controle e machucar justamente quem mais ama.","esquadrao":"Paragons"}'::jsonb, TRUE, NOW()
