INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Blindfold', 'Ruth Aldine', 'novatos', 'medio', '{"iniciativa":16,"stats":{"destreza":4,"força":3,"corpo":4,"inteligência":7,"vontade":7,"mente":9,"influência":5,"aura":6,"espírito":9},"temas":[{"nome":"Olhos que Não Precisam Ver","poder":[{"texto":"Nascida Sem Olhos e Ainda Assim Percebe Tudo"},{"texto":"Precognição de Eventos Trágicos"},{"texto":"Sente Presenças Sobrenaturais e Espíritos"},{"texto":"Interpretação de Sinais e Presságios"},{"texto":"Percepção Além dos Cinco Sentidos"},{"texto":"Sente o Fio do Destino de Quem Está por Perto"},{"texto":"Detecta Mentiras pela Vibração da Voz"}],"fraqueza":[]},{"nome":"Voz dos Presságios","poder":[{"texto":"Fala em Enigmas que Revelam Verdades Ocultas"},{"texto":"Avisa Perigos Antes que Aconteçam"},{"texto":"Sente a Morte se Aproximando de Alguém"},{"texto":"Guia os Aliados por Instruções Enigmáticas Precisas"}],"fraqueza":[]},{"nome":"Serena e Enigmática","poder":[{"texto":"Calma Perturbadora Diante do Caos"},{"texto":"Sabedoria que Assusta e Acalma ao Mesmo Tempo"},{"texto":"Gentileza Genuína sob a Aura Sombria"},{"texto":"Aceitação Tranquila do Próprio Dom"}],"fraqueza":[{"texto":"Incompreendida e Isolada pelos Colegas"}]},{"nome":"Fardo da Visão","poder":[],"fraqueza":[{"texto":"Não Pode Evitar o Que Vê Acontecer"},{"texto":"Exaustão Mental por Excesso de Presságios"},{"texto":"Dificuldade em Se Fazer Entender"}]}],"tags":[{"texto":"Nascida Sem Olhos e Ainda Assim Percebe Tudo"},{"texto":"Precognição de Eventos Trágicos"},{"texto":"Sente Presenças Sobrenaturais e Espíritos"},{"texto":"Interpretação de Sinais e Presságios"},{"texto":"Percepção Além dos Cinco Sentidos"},{"texto":"Sente o Fio do Destino de Quem Está por Perto"},{"texto":"Detecta Mentiras pela Vibração da Voz"},{"texto":"Fala em Enigmas que Revelam Verdades Ocultas"},{"texto":"Avisa Perigos Antes que Aconteçam"},{"texto":"Sente a Morte se Aproximando de Alguém"},{"texto":"Guia os Aliados por Instruções Enigmáticas Precisas"},{"texto":"Calma Perturbadora Diante do Caos"},{"texto":"Sabedoria que Assusta e Acalma ao Mesmo Tempo"},{"texto":"Gentileza Genuína sob a Aura Sombria"},{"texto":"Aceitação Tranquila do Próprio Dom"}],"descricao":"Ruth Aldine nasceu sem olhos e, mesmo assim, enxerga mais do que qualquer aluno do Instituto — presságios, mortes futuras, verdades que ninguém quer ouvir. Fala quase sempre em enigmas, o que a torna tão fascinante quanto perturbadora para quem cruza seu caminho pela primeira vez. Nos Paladins, é tratada com uma mistura de reverência e desconforto, algo que ela aceita com uma calma quase sobrenatural. Por trás da aura sombria, esconde uma gentileza genuína e o peso solitário de nunca poder desviar o olhar do que vê.","esquadrao":"Paladins"}'::jsonb, TRUE, NOW()
