INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Wing', 'Pedro Nunez', 'novatos', 'medio', '{"iniciativa":15,"stats":{"destreza":6,"força":4,"corpo":5,"inteligência":5,"vontade":5,"mente":5,"influência":4,"aura":5,"espírito":5},"temas":[{"nome":"Asas Insetoides em Formação","poder":[{"texto":"Par de Asas Insetoides Cresce das Costas"},{"texto":"Voo Instável mas Funcional"},{"texto":"Reflexos Rápidos ao Voar em Curtas Distâncias"},{"texto":"Casulo Protetor Improvisado com as Asas"},{"texto":"Camuflagem Parcial ao Dobrar as Asas"},{"texto":"Salto Impulsionado pelas Asas em Emergências"}],"fraqueza":[]},{"nome":"Mutação em Desenvolvimento","poder":[{"texto":"Sente Mudanças Físicas Contínuas no Próprio Corpo"},{"texto":"Adaptação Gradual ao Novo Corpo"},{"texto":"Instinto de Sobrevivência Aguçado"},{"texto":"Percepção Sensorial Ampliada nas Antenas em Formação"},{"texto":"Resistência a Toxinas Ambientais"}],"fraqueza":[]},{"nome":"Quieto e Observador","poder":[{"texto":"Discrição Natural que Passa Despercebida"},{"texto":"Lealdade Silenciosa aos Paladins"},{"texto":"Vontade de Provar Que Vale a Pena Confiar Nele"},{"texto":"Talento para Desenho Técnico e Mecânica"}],"fraqueza":[{"texto":"Vergonha da Própria Aparência"}]},{"nome":"Mutação Instável","poder":[],"fraqueza":[{"texto":"Asas Ainda Frágeis e Propensas a Falhar"},{"texto":"Dores Físicas Durante Surtos de Crescimento"},{"texto":"Medo de Nunca Terminar de Se Transformar"}]}],"tags":[{"texto":"Par de Asas Insetoides Cresce das Costas"},{"texto":"Voo Instável mas Funcional"},{"texto":"Reflexos Rápidos ao Voar em Curtas Distâncias"},{"texto":"Casulo Protetor Improvisado com as Asas"},{"texto":"Camuflagem Parcial ao Dobrar as Asas"},{"texto":"Salto Impulsionado pelas Asas em Emergências"},{"texto":"Sente Mudanças Físicas Contínuas no Próprio Corpo"},{"texto":"Adaptação Gradual ao Novo Corpo"},{"texto":"Instinto de Sobrevivência Aguçado"},{"texto":"Percepção Sensorial Ampliada nas Antenas em Formação"},{"texto":"Resistência a Toxinas Ambientais"},{"texto":"Discrição Natural que Passa Despercebida"},{"texto":"Lealdade Silenciosa aos Paladins"},{"texto":"Vontade de Provar Que Vale a Pena Confiar Nele"},{"texto":"Talento para Desenho Técnico e Mecânica"}],"descricao":"Pedro Nunez ainda está descobrindo o que seu próprio corpo está se tornando: um par de asas insetoides frágeis que cresceram das costas sem aviso e ainda falham com frequência preocupante. Quieto e desconfiado da própria aparência, prefere observar de longe a chamar atenção para si nos corredores dos Paladins. Ainda assim, é leal e dedicado, sempre disposto a provar seu valor mesmo quando duvida de si mesmo. Sonha com o dia em que a mutação finalmente vai parar — e em que suas asas vão, enfim, funcionar direito.","esquadrao":"Paladins"}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Wing' AND is_global = TRUE);

