INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Glob Herman', 'Robert Herman', 'novatos', 'medio', '{"iniciativa":12,"stats":{"destreza":4,"força":6,"corpo":8,"inteligência":4,"vontade":5,"mente":4,"influência":4,"aura":5,"espírito":5},"temas":[{"nome":"Corpo de Cera Viva","poder":[{"texto":"Corpo Ceroso e Translúcido Extremamente Maleável"},{"texto":"Resistência a Cortes e Perfurações"},{"texto":"Absorve Impactos como Massa de Cera"},{"texto":"Regeneração Lenta de Ferimentos na Cera"},{"texto":"Flutua Levemente ao Se Tornar Mais Leve com o Calor"},{"texto":"Amortece Quedas com a Própria Massa Cerosa"}],"fraqueza":[]},{"nome":"Chama Emergente","poder":[{"texto":"Manipulação de Fogo Adquirida Após o Dia-M"},{"texto":"Combustão Parcial do Próprio Corpo Ceroso"},{"texto":"Rajadas de Fogo Ainda Instáveis"},{"texto":"Chamas Cicatrizam Feridas Cerosas Superficiais"},{"texto":"Aquecimento Corporal Controlado"}],"fraqueza":[]},{"nome":"Sobrevivente da Omega Gang","poder":[{"texto":"Experiência de Rua da Antiga Omega Gang"},{"texto":"Lealdade Reconquistada Após Pagar pelos Erros"},{"texto":"Humildade Forjada na Prisão"},{"texto":"Trabalho Duro para Reconstruir a Reputação"}],"fraqueza":[{"texto":"Cicatrizes Visíveis do Incêndio que Ele Mesmo Causou"}]},{"nome":"Passado que Pesa","poder":[],"fraqueza":[{"texto":"Culpa por Ferimentos Causados Durante o Motim de Xavier"},{"texto":"Controle do Fogo Ainda Imprevisível"},{"texto":"Desconfiança dos Outros Alunos por seu Histórico"}]}],"tags":[{"texto":"Corpo Ceroso e Translúcido Extremamente Maleável"},{"texto":"Resistência a Cortes e Perfurações"},{"texto":"Absorve Impactos como Massa de Cera"},{"texto":"Regeneração Lenta de Ferimentos na Cera"},{"texto":"Flutua Levemente ao Se Tornar Mais Leve com o Calor"},{"texto":"Amortece Quedas com a Própria Massa Cerosa"},{"texto":"Manipulação de Fogo Adquirida Após o Dia-M"},{"texto":"Combustão Parcial do Próprio Corpo Ceroso"},{"texto":"Rajadas de Fogo Ainda Instáveis"},{"texto":"Chamas Cicatrizam Feridas Cerosas Superficiais"},{"texto":"Aquecimento Corporal Controlado"},{"texto":"Experiência de Rua da Antiga Omega Gang"},{"texto":"Lealdade Reconquistada Após Pagar pelos Erros"},{"texto":"Humildade Forjada na Prisão"},{"texto":"Trabalho Duro para Reconstruir a Reputação"}],"descricao":"Robert Herman conhece bem o preço de errar: sua pele cerosa já pegou fogo por acidente, deixando cicatrizes visíveis de um passado violento como membro da Omega Gang de Quentin Quire. Depois de pagar por seus crimes na prisão, retornou ao Instituto — hoje baseado em Utopia — determinado a provar que mudou de verdade. Ganhou controle sobre o fogo após o Dia-M, uma reviravolta que ainda o assusta mais do que orgulha. Trabalha em silêncio, sem pedir desculpas em excesso, deixando que suas ações reconstruam aos poucos a confiança que perdeu.","esquadrao":"Omega Gang"}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Glob Herman' AND is_global = TRUE);

