  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Kid Omega' AND is_global = TRUE);

INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Radian', 'Christian Cord', 'novatos', 'medio', '{"iniciativa":17,"stats":{"destreza":6,"força":4,"corpo":5,"inteligência":6,"vontade":5,"mente":5,"influência":5,"aura":6,"espírito":5},"temas":[{"nome":"Luz Viva","poder":[{"texto":"Projeção de Feixes de Luz Concentrada"},{"texto":"Absorção de Luz Ambiente para Recarregar o Poder"},{"texto":"Criação de Clarões Cegantes"},{"texto":"Camuflagem por Manipulação de Reflexos Luminosos"},{"texto":"Voo por Propulsão de Luz"},{"texto":"Refração que Desvia Ataques à Distância"}],"fraqueza":[]},{"nome":"Rastro Radiante","poder":[{"texto":"Constructos Sólidos de Luz de Curta Duração"},{"texto":"Sinalização a Longa Distância com Luz"},{"texto":"Precisão em Feixes de Combate"},{"texto":"Feixe Cortante de Alta Precisão"},{"texto":"Ilumina Áreas Escuras Instantaneamente"}],"fraqueza":[]},{"nome":"Sentença Cumprida","poder":[{"texto":"Disciplina Adquirida Durante o Tempo na Prisão"},{"texto":"Determinação para Provar que Mudou"},{"texto":"Cautela Estratégica Aprendida da Pior Forma"},{"texto":"Trabalha em Dobro para Recuperar a Confiança dos Outros"}],"fraqueza":[{"texto":"Passado Criminal como Membro da Omega Gang"}]},{"nome":"Sombra do Dia-M","poder":[],"fraqueza":[{"texto":"Medo Constante de Perder os Poderes de Novo"},{"texto":"Desconfiança de Colegas por Seu Histórico"},{"texto":"Ansiedade sobre um Futuro Incerto"}]}],"tags":[{"texto":"Projeção de Feixes de Luz Concentrada"},{"texto":"Absorção de Luz Ambiente para Recarregar o Poder"},{"texto":"Criação de Clarões Cegantes"},{"texto":"Camuflagem por Manipulação de Reflexos Luminosos"},{"texto":"Voo por Propulsão de Luz"},{"texto":"Refração que Desvia Ataques à Distância"},{"texto":"Constructos Sólidos de Luz de Curta Duração"},{"texto":"Sinalização a Longa Distância com Luz"},{"texto":"Precisão em Feixes de Combate"},{"texto":"Feixe Cortante de Alta Precisão"},{"texto":"Ilumina Áreas Escuras Instantaneamente"},{"texto":"Disciplina Adquirida Durante o Tempo na Prisão"},{"texto":"Determinação para Provar que Mudou"},{"texto":"Cautela Estratégica Aprendida da Pior Forma"},{"texto":"Trabalha em Dobro para Recuperar a Confiança dos Outros"}],"descricao":"Christian Cord já usou a luz que emite tanto para ferir quanto, hoje, para sinalizar um arrependimento genuíno. Como membro da antiga Omega Gang, cumpriu pena por seus crimes e perdeu os poderes no Dia-M — só para vê-los, inexplicavelmente, retornar tempos depois. Hoje tenta reconstruir sua reputação entre os colegas mais desconfiados, treinando com uma disciplina que nunca teve quando era mais jovem. Carrega o medo constante de que tudo possa ser tirado dele outra vez, sem aviso.","esquadrao":"Omega Gang"}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Radian' AND is_global = TRUE);

INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Redneck', 'Vincent Stewart', 'novatos', 'medio', '{"iniciativa":11,"stats":{"destreza":5,"força":9,"corpo":8,"inteligência":3,"vontade":5,"mente":3,"influência":3,"aura":5,"espírito":4},"temas":[{"nome":"Força Bruta","poder":[{"texto":"Força Sobre-humana Capaz de Arrancar Concreto"},{"texto":"Resistência Física Elevada a Impactos"},{"texto":"Golpes que Derrubam Estruturas"},{"texto":"Salto de Longa Distância com as Pernas Reforçadas"},{"texto":"Aguenta Golpes que Derrubariam um Adulto Comum"},{"texto":"Levanta Objetos Vários Vezes Maiores que o Próprio Corpo"}],"fraqueza":[]},{"nome":"Peso Morto","poder":[{"texto":"Ancoragem Física para Resistir a Empurrões"},{"texto":"Presença Intimidadora pelo Tamanho"},{"texto":"Braço de Ferro em Disputas de Força"},{"texto":"Estabilidade Total ao Segurar Posição em Combate"},{"texto":"Amortece Quedas de Grande Altura"}],"fraqueza":[]},{"nome":"Peão da Omega Gang","poder":[{"texto":"Lealdade Cega a Quem Lhe Dá Ordens Claras"},{"texto":"Simplicidade que o Torna Fácil de Manipular por Bons ou Maus"},{"texto":"Coragem Bruta sem Hesitação"},{"texto":"Protetor Fiel de Quem Considera Aliado"}],"fraqueza":[{"texto":"Passado Criminal como Membro da Omega Gang"}]},{"nome":"Cicatriz do Dia-M","poder":[],"fraqueza":[{"texto":"Trauma de Perder os Poderes Repentinamente"},{"texto":"Insegurança Intelectual Profunda"},{"texto":"Medo de Ser Descartado se Não For Forte"}]}],"tags":[{"texto":"Força Sobre-humana Capaz de Arrancar Concreto"},{"texto":"Resistência Física Elevada a Impactos"},{"texto":"Golpes que Derrubam Estruturas"},{"texto":"Salto de Longa Distância com as Pernas Reforçadas"},{"texto":"Aguenta Golpes que Derrubariam um Adulto Comum"},{"texto":"Levanta Objetos Vários Vezes Maiores que o Próprio Corpo"},{"texto":"Ancoragem Física para Resistir a Empurrões"},{"texto":"Presença Intimidadora pelo Tamanho"},{"texto":"Braço de Ferro em Disputas de Força"},{"texto":"Estabilidade Total ao Segurar Posição em Combate"},{"texto":"Amortece Quedas de Grande Altura"},{"texto":"Lealdade Cega a Quem Lhe Dá Ordens Claras"},{"texto":"Simplicidade que o Torna Fácil de Manipular por Bons ou Maus"},{"texto":"Coragem Bruta sem Hesitação"},{"texto":"Protetor Fiel de Quem Considera Aliado"}],"descricao":"Vincent Stewart é pura força bruta com um coração mais gentil do que aparenta, algo que poucos se dão ao trabalho de descobrir por trás de sua reputação de ex-membro da Omega Gang. Perdeu os poderes no Dia-M e viveu isso como uma ferida profunda, um vazio que a força de vontade sozinha não conseguia preencher. De volta ao Instituto, é leal até o fim com quem lhe dá uma chance — simples, direto, e sempre pronto para se colocar entre o perigo e um amigo. Sua maior luta é interna: provar, a si mesmo antes de qualquer outra pessoa, que vale mais do que os erros que cometeu.","esquadrao":"Omega Gang"}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Redneck' AND is_global = TRUE);

INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Tattoo', 'Christine Cord', 'novatos', 'medio', '{"iniciativa":16,"stats":{"destreza":6,"força":4,"corpo":5,"inteligência":5,"vontade":5,"mente":5,"influência":5,"aura":6,"espírito":6},"temas":[{"nome":"Tatuagens Vivas","poder":[{"texto":"Tatuagens na Própria Pele Ganham Vida ao Se Soltarem"},{"texto":"Criaturas de Tinta que Obedecem seus Comandos"},{"texto":"Múltiplas Tatuagens Ativas Simultaneamente"},{"texto":"Redesenha Novas Tatuagens sob a Pele em Minutos"},{"texto":"Controla a Textura e Cor das Criaturas de Tinta"},{"texto":"Sente Tudo que Suas Criaturas Percebem"}],"fraqueza":[]},{"nome":"Enxame de Tinta","poder":[{"texto":"Criaturas Animadas com Formas Variadas (aves, feras, lâminas)"},{"texto":"Coordenação Tática entre as Criaturas"},{"texto":"Reforma as Tatuagens Após Serem Destruídas"},{"texto":"Formação de Enxame para Emboscadas"},{"texto":"Camuflagem das Criaturas contra Superfícies Escuras"}],"fraqueza":[]},{"nome":"Irmã Gêmea da Omega Gang","poder":[{"texto":"Vínculo Próximo com o Irmão Radian"},{"texto":"Lealdade Feroz à Família Cord"},{"texto":"Confiança Construída aos Poucos com os Novos Colegas"},{"texto":"Determinação de Reconstruir sua Reputação junto com o Irmão"}],"fraqueza":[{"texto":"Passado Criminal como Membro da Omega Gang"}]},{"nome":"Tinta que Pode Falhar","poder":[],"fraqueza":[{"texto":"Criaturas Consomem Energia Vital ao Serem Usadas"},{"texto":"Pele Fica Vulnerável Quando as Tatuagens Estão Fora do Corpo"},{"texto":"Medo de Repetir os Erros do Passado"}]}],"tags":[{"texto":"Tatuagens na Própria Pele Ganham Vida ao Se Soltarem"},{"texto":"Criaturas de Tinta que Obedecem seus Comandos"},{"texto":"Múltiplas Tatuagens Ativas Simultaneamente"},{"texto":"Redesenha Novas Tatuagens sob a Pele em Minutos"},{"texto":"Controla a Textura e Cor das Criaturas de Tinta"},{"texto":"Sente Tudo que Suas Criaturas Percebem"},{"texto":"Criaturas Animadas com Formas Variadas (aves, feras, lâminas)"},{"texto":"Coordenação Tática entre as Criaturas"},{"texto":"Reforma as Tatuagens Após Serem Destruídas"},{"texto":"Formação de Enxame para Emboscadas"},{"texto":"Camuflagem das Criaturas contra Superfícies Escuras"},{"texto":"Vínculo Próximo com o Irmão Radian"},{"texto":"Lealdade Feroz à Família Cord"},{"texto":"Confiança Construída aos Poucos com os Novos Colegas"},{"texto":"Determinação de Reconstruir sua Reputação junto com o Irmão"}],"descricao":"Christine Cord carrega a arte na própria pele — literalmente. Suas tatuagens ganham vida e se soltam do corpo como criaturas obedientes, uma habilidade tão fascinante quanto foi perigosa nas mãos erradas da antiga Omega Gang. Ao lado do irmão Radian, cumpriu pena e perdeu os poderes no Dia-M, apenas para vê-los renascer, junto com a chance de recomeçar. Reservada no início, vai revelando aos poucos a lealdade feroz que reserva para quem conquista sua confiança — assim como suas tatuagens revelam quem ela realmente é.","esquadrao":"Omega Gang"}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Tattoo' AND is_global = TRUE);

